		err = migrateOSS(ctx, as)
		require.NoError(t, err)
	})

	t.Run("GithubConnector", func(t *testing.T) {
		as := newTestAuthServer(t)
		clock := clockwork.NewFakeClock()
		as.SetClock(clock)

		connector := types.NewGithubConnector("github", types.GithubConnectorSpecV3{
